def trig_single_function_simplification_bonus(prompts, completions, answer, **kwargs):
    import re
    def _response(c):
        try:
            if isinstance(c, list) and c:
                return c[0].get('content', '') or ''
        except Exception:
            pass
        return ''
    trig_re = re.compile(r'(?<![A-Za-z])(sin|cos|tan|cot|sec|csc)(?![A-Za-z])')
    scores = []
    for completion, true_answer in zip(completions, answer):
        resp = _response(completion)
        try:
            sol = extract_solution(resp)
        except Exception:
            sol = None
        if sol is None:
            m = re.search(r'<solution>(.*?)</solution>', resp, re.DOTALL)
            sol = m.group(1).strip() if m else ''
        sol = sol.strip()
        gt = '' if true_answer is None else str(true_answer)
        try:
            correct = bool(sol) and is_correct(sol, gt)
        except Exception:
            correct = False
        gt_low = gt.lower().replace(chr(92), '')
        gt_trigs = trig_re.findall(gt_low)
        if not gt_trigs:
            scores.append(5.0 if correct else 0.0)
            continue
        if correct:
            scores.append(5.0)
            continue
        sol_low = sol.lower().replace(chr(92), '')
        sol_trigs = trig_re.findall(sol_low)
        if not sol:
            scores.append(-2.0)
        elif len(sol_trigs) == 1:
            if sol_trigs[0] in gt_trigs:
                scores.append(1.5)
            else:
                scores.append(0.5)
        elif len(sol_trigs) > 1:
            scores.append(-1.0)
        else:
            scores.append(-1.5)
    return scores

def numeric_precision_formatting(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        solution = extract_solution(response)

        if solution is None:
            scores.append(-1.0)
            continue

        is_corr = is_correct(solution, true_answer)

        # Check if ground truth is a decimal with specific precision
        gt_decimals = re.search(r'\.(\d+)', true_answer)
        if gt_decimals:
            gt_prec = len(gt_decimals.group(1))

            # Check prediction decimals
            pred_decimals = re.search(r'\.(\d+)', solution)
            if pred_decimals:
                pred_prec = len(pred_decimals.group(1))

                if is_corr:
                    # Exact match or slightly more precision is good
                    if pred_prec == gt_prec:
                        score = 4.0
                    elif pred_prec > gt_prec:
                        score = 3.5
                    else:
                        score = 3.0
                else:
                    # Wrong answer, but did they try to match format?
                    if pred_prec >= gt_prec - 1:
                        score = -0.5
                    else:
                        score = -1.0
            else:
                # No decimal in prediction when GT has one
                if is_corr:
                    score = 3.0
                else:
                    score = -1.5
        else:
            # GT is integer or fraction
            if is_corr:
                # Penalize unnecessary decimals for integer GT
                if re.search(r'\.', solution):
                    score = 3.5
                else:
                    score = 4.5
            else:
                score = -1.0

        scores.append(score)
    return scores

def interval_bracket_correctness(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        solution = extract_solution(response)

        if solution is None:
            scores.append(-1.0)
            continue

        is_corr = is_correct(solution, true_answer)

        # Check if GT is an interval
        if re.match(r'^[\(\[].*[\)\]]$', true_answer.strip()):
            gt_open = true_answer.strip()[0] in ['(', '[']
            gt_close = true_answer.strip()[-1] in [')', ']']

            # Extract pred brackets
            pred_str = solution.strip()
            if pred_str and pred_str[0] in ['(', '[', '(', '['] and pred_str[-1] in [')', ']', ')', ']']:
                pred_open = pred_str[0] in ['(', '[']
                pred_close = pred_str[-1] in [')', ']']

                if is_corr:
                    score = 5.0
                else:
