                        score = -0.2
                    else:
                        score = -0.8
            else:
                # Not an interval format
                if is_corr:
                    score = 4.0 # Maybe LaTeX interval?
                else:
                    score = -1.5
        else:
            # GT is not an interval
            if is_corr:
                score = 4.5
            else:
                # Penalize if model outputs interval when GT is not
                if re.match(r'^[\(\[].*[\)\]]$', solution.strip()):
                    score = -1.2
                else:
                    score = -1.0

        scores.append(score)
    return scores

