def fraction_reduced_form_bonus(prompts, completions, answer, **kwargs):
    import re
    from math import gcd
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        solution = extract_solution(response)

        if solution is None:
            scores.append(-1.0)
            continue

        is_corr = is_correct(solution, true_answer)

        # Helper to check if a string is a reduced fraction
        def is_reduced_frac(s):
            m = re.match(r'^\\frac\{(\d+)\}\{(\d+)\}$', s.strip())
            if not m:
                return None
            num = int(m.group(1))
            den = int(m.group(2))
            if den == 0:
                return False
            return gcd(num, den) == 1

        # Check if GT is a fraction
        gt_frac_match = re.match(r'^\\frac\{(\d+)\}\{(\d+)\}$', true_answer.strip())
        if gt_frac_match:
            gt_num = int(gt_frac_match.group(1))
            gt_den = int(gt_frac_match.group(2))
            gt_gcd = gcd(gt_num, gt_den)
            gt_is_reduced = (gt_gcd == 1)

            pred_frac_match = re.match(r'^\\frac\{(\d+)\}\{(\d+)\}$', solution.strip())
            if pred_frac_match:
                pred_num = int(pred_frac_match.group(1))
                pred_den = int(pred_frac_match.group(2))
                pred_gcd = gcd(pred_num, pred_den)
                pred_is_reduced = (pred_gcd == 1)

                if is_corr:
                    if pred_is_reduced:
                        score = 5.0
                    else:
                        score = 4.0 # Correct but not simplified
                else:
                    # Check if it's equivalent but not simplified
                    if pred_den != 0 and gt_den != 0:
                        if pred_num * gt_den == gt_num * pred_den:
                            if pred_is_reduced:
                                score = 2.0 # Equivalent and reduced, but is_correct failed? Maybe sign?
                            else:
                                score = 1.0
                        else:
                            score = -1.0
                    else:
                        score = -1.0
            else:
                # Not a fraction format
                if is_corr:
                    score = 4.0
                else:
                    score = -1.0
        else:
            if is_corr:
                # Penalize if GT is not fraction but pred is unreduced fraction
                pred_frac_match = re.match(r'^\\frac\{(\d+)\}\{(\d+)\}$', solution.strip())
                if pred_frac_match:
                    pred_num = int(pred_frac_match.group(1))
                    pred_den = int(pred_frac_match.group(2))
                    if gcd(pred_num, pred_den) != 1:
                        score = 3.5
                    else:
                        score = 4.5
                else:
                    score = 4.5
            else:
                score = -1.0

        scores.append(score)
    return scores

