def variable_consistency_check(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        thinking = extract_thinking(response)
        solution = extract_solution(response)

        if thinking is None or solution is None:
            scores.append(-0.5)
            continue

        is_corr = is_correct(solution, true_answer)

        # Extract variables from thinking (single letters)
        thinking_vars = set(re.findall(r'\b[a-zA-Z]\b', thinking))

        # Check for inconsistent definitions (e.g., x=1, x=2)
        # Simple check: find all 'var = value' patterns
        definitions = re.findall(r'\b([a-zA-Z])\s*=\s*([\d\-\.]+)', thinking)
        var_values = {}
        for var, val in definitions:
            if var not in var_values:
                var_values[var] = []
            var_values[var].append(val)

        inconsistencies = 0
        for var, vals in var_values.items():
            unique_vals = set(vals)
            if len(unique_vals) > 1:
                inconsistencies += 1

        if is_corr:
            if inconsistencies == 0:
                score = 5.0
            else:
                score = 3.0 # Correct answer despite messy logic
        else:
            if inconsistencies > 2:
                score = -1.5 # Highly inconsistent
            elif inconsistencies > 0:
                score = -1.0
            else:
                score = -0.8

        scores.append(score)
    return scores

def numeric_sign_accuracy(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        response = completion[0]['content']
        solution = extract_solution(response)

        if solution is None:
            scores.append(-1.0)
            continue

        is_corr = is_correct(solution, true_answer)

        # Extract numeric value from GT
        def get_sign(s):
            # Remove LaTeX fractions if present
            frac_match = re.match(r'^\\frac\{(-?\d+)\}\{(-?\d+)\}$', s.strip())
            if frac_match:
                num = int(frac_match.group(1))
                den = int(frac_match.group(2))
                if den == 0:
                    return 0
                return 1 if num/den > 0 else -1

            # Simple numeric extraction
            num_match = re.search(r'[-+]?\d+\.?\d*', s.strip())
            if num_match:
                val = float(num_match.group(0))
                if val > 0:
                    return 1
                elif val < 0:
                    return -1
                else:
                    return 0
            return None

        gt_sign = get_sign(true_answer)
        pred_sign = get_sign(solution)

        if gt_sign is None or pred_sign is None:
            if is_corr:
                score = 4.0
            else:
                score = -1.0
        else:
            if is_corr:
                score = 5.0
            else:
                if gt_sign == pred_sign:
                    score = -0.5 # Wrong magnitude, right sign
                else:
                    score = -1.5 # Wrong sign is a big error

        scores.append(score)
    return scores

